<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,shallowReactive,watch} from 'vue';
import type {Comparison,Draft,DraftLine,GeneratedLink,Hospital,Manufacturer,MarkupMethod,OrderSummary,OrderView,PurchaseInput,SupplierTask} from '@quote/contracts';
import {BusinessOperations} from '../business-pending';
import type {PcApi} from '../api';
import {pricingInputs,recommendation,restoreMarkup,validPositive,type MarkupState} from '../../../mini/src/domain';
import QuoteDelivery from './QuoteDelivery.vue';
import SourceFiles from './SourceFiles.vue';
import CatalogPanel from './CatalogPanel.vue';
import PriceHistory from './PriceHistory.vue';
import type {CatalogVariant} from '../../../../packages/master-client/src';
import type {FinanceTarget} from '../../../../packages/finance-client/src';
const props=defineProps<{api:Pick<PcApi,'get'|'post'|'write'|'getImage'>;userId:string}>();const emit=defineEmits<{busyChanged:[value:boolean];manageFinance:[target:FinanceTarget]}>();
const operations=shallowReactive(new BusinessOperations(props.userId,p=>props.api.get(p),(p,m,b,k)=>props.api.write(p,m,b,k),window.localStorage));
const sourceBusy=ref(false),catalogBusy=ref(false),catalogOpen=ref(false),historyBusy=ref(false),referenceLineId=ref<string|null>(null);
const working=ref(false),childBusy=ref(false),dirty=ref(false),error=ref(''),notice=ref(''),tab=ref<'orders'|'purchase'|'inquiry'|'pricing'|'delivery'>('orders');
const order=ref<OrderView|null>(null),orders=ref<OrderSummary[]>([]),hospitals=ref<Hospital[]>([]),manufacturers=ref<Manufacturer[]>([]),comparison=ref<Comparison|null>(null),draft=ref<Draft|null>(null);
const hospitalId=ref(''),purchaserId=ref(''),receivedDate=ref(today()),lines=ref<PurchaseInput[]>([emptyLine()]),factory=ref(['','']),generated=ref<Record<string,GeneratedLink>>({});
const lifecycleAction=ref<'revisions'|'void'|null>(null),lifecycleReason=ref('');
const taskAction=ref<{task:SupplierTask;action:'regenerate-link'|'requote'|'cancel'}|null>(null),reason=ref(''),selected=ref<string[]>([]),method=ref<MarkupMethod|' '>(' '),parameter=ref(''),batchScope=ref<'all'|'selected'>('all'),undo=ref<(MarkupState&{purchaseLineId:string})[]|null>(null);
const busy=computed(()=>working.value||childBusy.value||sourceBusy.value||catalogBusy.value||historyBusy.value||!!operations.pending);const writable=computed(()=>!order.value||order.value.writable&&!['completed','voided'].includes(order.value.status));
const referenceLine=computed(()=>draft.value?.lines.find(l=>l.purchaseLineId===referenceLineId.value));
const referencePurchaseLine=computed(()=>order.value?.lines.find(l=>l.id===referenceLine.value?.purchaseLineId));
watch(()=>[order.value?.id,order.value?.hospitalId,order.value?.revisionId,draft.value,tab.value],()=>{referenceLineId.value=null;},{flush:'sync'});
const hospital=computed(()=>hospitals.value.find(h=>h.id===hospitalId.value));const methods=[['fixed','固定加价'],['percent','比例加价 %'],['multiplier','高开倍率']] as const;
const labels:Record<string,string>={draft:'采购校对',frozen:'待询价',quote_draft:'计价中',quote_exported:'已导出',quote_sent:'待医院确认',completed:'已完成',voided:'已作废'};
function today(){return new Date(Date.now()+8*3600000).toISOString().slice(0,10);}function emptyLine():PurchaseInput{return {name:'',spec:'',quantity:'',checked:false,remark:'',sourceType:'custom_input'};}
function changed(){dirty.value=true;notice.value='有未保存修改。';}function checkLeave(){return !dirty.value||window.confirm('放弃当前未保存修改？');}
watch(()=>busy.value||dirty.value||!!lifecycleAction.value,v=>emit('busyChanged',v),{immediate:true});watch(hospitalId,()=>{if(!hospital.value?.purchasers.some(p=>p.id===purchaserId.value))purchaserId.value=hospital.value?.purchasers[0]?.id||'';});
async function run(work:()=>Promise<void>){if(working.value||childBusy.value||sourceBusy.value||catalogBusy.value||historyBusy.value)return;working.value=true;error.value='';try{await work();}catch(e){error.value=e instanceof Error?e.message:'操作未完成，请核对。';}finally{working.value=false;}}
async function bootstrap(){const [a,b]=await Promise.all([props.api.get<{hospitals:Hospital[];manufacturers:Manufacturer[]}>('/sales/bootstrap'),props.api.get<{items:OrderSummary[]}>('/sales/purchase-orders')]);hospitals.value=a.hospitals;manufacturers.value=a.manufacturers;orders.value=b.items;hospitalId.value||=a.hospitals[0]?.id||'';factory.value=[a.manufacturers[0]?.id||'',a.manufacturers[1]?.id||''];}
function hydrate(o:OrderView){order.value=o;lines.value=o.lines.map(l=>({...l}));hospitalId.value=o.hospitalId;purchaserId.value=o.purchaserUserId;receivedDate.value=o.receivedDate;dirty.value=false;}
async function load(){if(order.value)hydrate(await props.api.get<OrderView>('/sales/purchase-orders/'+order.value.id));}
async function comparisonLoad(){if(order.value)comparison.value=await props.api.get<Comparison>('/sales/purchase-orders/'+order.value.id+'/comparison');}
async function open(id:string){if(busy.value||!checkLeave())return;await run(async()=>{generated.value={};draft.value=null;comparison.value=null;hydrate(await props.api.get<OrderView>('/sales/purchase-orders/'+id));tab.value=order.value!.status==='draft'?'purchase':['completed','voided','quote_exported','quote_sent'].includes(order.value!.status)?'delivery':'inquiry';if(tab.value==='inquiry')await comparisonLoad();});}
async function start(){if(busy.value||!checkLeave())return;order.value=null;draft.value=null;comparison.value=null;generated.value={};lines.value=[emptyLine()];receivedDate.value=today();dirty.value=false;tab.value='purchase';}
async function home(){if(busy.value||!checkLeave())return;dirty.value=false;tab.value='orders';await run(bootstrap);}
async function savePurchase(){if(!writable.value)throw new Error('当前订单只读。');if(!hospitalId.value||!purchaserId.value||!receivedDate.value||lines.value.some(l=>!l.name.trim()||!validPositive(l.quantity)))throw new Error('请填写医院、采购员、实际接收日期及每行品名和有效数量。');const body=lines.value.map(l=>({...(l.id?{id:l.id}:{}),name:l.name,spec:l.spec,quantity:l.quantity,checked:l.checked,remark:l.remark||'',sourceType:l.sourceType||'custom_input',itemId:l.itemId??null,itemVariantId:l.itemVariantId??null,sourceFileId:l.sourceFileId??null,parsingJobId:l.parsingJobId??null,sourceRowNumber:l.sourceRowNumber??null}));const r=order.value?await operations.mutate<OrderView>('保存采购校对',`/sales/purchase-orders/${order.value.id}/revisions/${order.value.revisionId}/lines`,'PUT',{expectedVersion:order.value.version,lines:body,...order.value.receivedDateEditable?{receivedDate:receivedDate.value}:{}}):await operations.mutate<OrderView>('新建采购单','/sales/purchase-orders','POST',{hospitalId:hospitalId.value,purchaserUserId:purchaserId.value,receivedDate:receivedDate.value,lines:body});hydrate(r);notice.value='采购草稿已保存。';}
function lifecycle(action:'revisions'|'void'){if(busy.value||!order.value||!writable.value)return;if(dirty.value){error.value='请先保存或放弃当前修改，再操作采购修订或整单作废。';return;}lifecycleAction.value=action;lifecycleReason.value='';}
async function commitLifecycle(){if(!lifecycleAction.value||!order.value||!lifecycleReason.value.trim())return;const action=lifecycleAction.value;await run(async()=>{const value=await operations.mutate<OrderView>(action==='revisions'?'新建采购修订':'整单作废','/sales/purchase-orders/'+order.value!.id+'/'+action,'POST',{expectedVersion:order.value!.version,reason:lifecycleReason.value});hydrate(value);comparison.value=null;draft.value=null;generated.value={};selected.value=[];undo.value=null;lifecycleAction.value=null;tab.value=action==='revisions'?'purchase':'delivery';notice.value=action==='revisions'?'新修订已建立，须重新逐行校对和询价；旧版保持历史，不再恢复。':'整张采购单已作废，文件和历史保留。';});}
async function createSourceDraft(){await run(async()=>{if(order.value)return;if(!hospitalId.value||!purchaserId.value||!receivedDate.value)throw new Error('请先选择医院、采购员和实际接收日期。');if(lines.value.some(l=>l.name||l.spec||l.quantity||l.remark))throw new Error('已有手工输入，请先保存完整明细，或放弃修改后创建原单资料草稿。');const value=await operations.mutate<OrderView>('新建原单资料草稿','/sales/purchase-orders','POST',{hospitalId:hospitalId.value,purchaserUserId:purchaserId.value,receivedDate:receivedDate.value,lines:[]});hydrate(value);notice.value='原单资料草稿已建立，可上传图片或表格；应用候选后仍需逐行校对。';});}
function chooseCatalog(value:CatalogVariant){if(busy.value||!writable.value)return;if(lines.value.length>=200){error.value='每单最多200行。';return;}const line={...emptyLine(),name:value.name,spec:value.specification,sourceType:'product_library' as const,itemId:value.itemId,itemVariantId:value.variantId};if(lines.value.length===1&&!lines.value[0].name&&!lines.value[0].quantity&&!lines.value[0].spec)lines.value=[line];else lines.value.push(line);catalogOpen.value=false;changed();}
async function freeze(){if(!window.confirm('冻结采购明细后厂家将严格按此规格与 kg 单位报价，确认继续？'))return;await run(async()=>{if(lines.value.some(l=>!l.checked))throw new Error('请先逐行校对并勾选全部采购行。');await savePurchase();await operations.mutate('冻结采购单',`/sales/purchase-orders/${order.value!.id}/revisions/${order.value!.revisionId}/freeze`,'POST',{expectedVersion:order.value!.version});await load();await comparisonLoad();tab.value='inquiry';});}
function task(slot:number){return order.value?.tasks.find(t=>t.slotNo===slot);}
async function assign(slot:1|2){await run(async()=>{if(!factory.value[slot-1])throw new Error('请选择厂家。');await operations.mutate('选择询价厂家',`/sales/purchase-order-revisions/${order.value!.revisionId}/supplier-tasks`,'POST',{expectedVersion:order.value!.version,slotNo:slot,manufacturerId:factory.value[slot-1]});await load();await comparisonLoad();});}
async function link(t:SupplierTask){await run(async()=>{const v=await operations.mutate<GeneratedLink>('生成厂家链接',`/supplier-tasks/${t.id}/generate-link`,'POST',{expectedVersion:order.value!.version});if(v.url)generated.value[t.id]=v;await load();notice.value=v.url?'链接已生成，请复制并自行发给对应厂家。':'原链接不可恢复，请明确重新生成。';});}
async function executeTaskAction(){if(!taskAction.value||!reason.value.trim())return;const {task:t,action}=taskAction.value;await run(async()=>{const r=await operations.mutate<GeneratedLink>('厂家任务'+action,`/supplier-tasks/${t.id}/${action}`,'POST',{expectedVersion:order.value!.version,reason:reason.value,...action==='regenerate-link'?{expectedLinkId:t.linkId}:{},...action==='requote'?{expectedSubmissionId:t.submissionId}:{}});delete generated.value[t.id];if(r.url)generated.value[t.id]=r;taskAction.value=null;reason.value='';await load();await comparisonLoad();notice.value='任务已更新，原链接/旧页面失效。';});}
async function loadDraft(){draft.value=await props.api.get<Draft>('/sales/purchase-orders/'+order.value!.id+'/draft');dirty.value=false;undo.value=null;tab.value='pricing';}
async function enter(){if(order.value?.quoteId&&!order.value.draftId){await changeTab('delivery');return;}if(comparison.value?.submittedCount===1&&!window.confirm('另一家尚未完整提交，确认提前计价？'))return;await run(async()=>{draft.value=await operations.mutate<Draft>('进入计价',`/sales/purchase-orders/${order.value!.id}/enter-pricing`,'POST',{expectedVersion:order.value!.version,allowEarly:comparison.value?.submittedCount===1});await load();tab.value='pricing';});}
function batch(){try{if(!draft.value||method.value===' ')throw new Error('请选择加价方式并填写参数。');const targets=draft.value.lines.filter(l=>l.kind==='priced'&&l.baseValid&&(batchScope.value==='all'||selected.value.includes(l.purchaseLineId)));if(!targets.length)throw new Error('没有可计价的目标行。');const updates=targets.map(l=>({l,value:recommendation(l.basePrice!,method.value as MarkupMethod,parameter.value)}));if(!window.confirm(`更新 ${updates.length} 行推荐价？最终价需另行采用和确认。`))return;undo.value=targets.map(l=>({purchaseLineId:l.purchaseLineId,markupMethod:l.markupMethod,parameterValue:l.parameterValue,recommendedPrice:l.recommendedPrice}));updates.forEach(({l,value})=>{l.markupMethod=method.value as MarkupMethod;l.parameterValue=parameter.value;l.recommendedPrice=value;});changed();}catch(e){error.value=(e as Error).message;}}
function undoBatch(){if(draft.value&&undo.value){draft.value.lines=draft.value.lines.map(l=>{const old=undo.value!.find(x=>x.purchaseLineId===l.purchaseLineId);return old?restoreMarkup(l,old):l;});undo.value=null;changed();}}
function base(l:DraftLine,event:Event){const id=(event.target as HTMLSelectElement).value,c=comparison.value?.lines.find(x=>x.purchaseLineId===l.purchaseLineId)?.cells.find(c=>c.supplierQuoteLineId===id&&c.state==='quoted');if(!c)return;l.baseSupplierQuoteLineId=id;l.baseManufacturerName=c.manufacturerName;l.basePrice=c.price;l.baseValid=true;l.selectionMode='manual';l.finalConfirmed=false;l.recommendedPrice=l.markupMethod&&l.parameterValue!==null?recommendation(c.price!,l.markupMethod,l.parameterValue):null;changed();}
function finalChanged(l:DraftLine){l.finalConfirmed=false;changed();}function adoptRecommended(l:DraftLine){if(l.recommendedPrice){l.finalPrice=l.recommendedPrice;finalChanged(l);}}
async function saveDraft(){await run(async()=>{const d=draft.value!;draft.value=await operations.mutate<Draft>('保存计价草稿',`/quotes/${d.quoteId}/versions/${d.id}/draft`,'PUT',{expectedVersion:d.version,hospitalValidUntil:d.hospitalValidUntil,lines:pricingInputs(d.lines)});dirty.value=false;undo.value=null;await load();tab.value='delivery';});}
async function adopt(){if(dirty.value){error.value='请先保存当前计价修改。';return;}if(!window.confirm('采用最新厂家报价快照？已保存最终价保留，变化基准需重新确认。'))return;await run(async()=>{const d=draft.value!;draft.value=await operations.mutate<Draft>('主动采用新报价',`/quotes/${d.quoteId}/versions/${d.id}/adopt-latest-supplier-quotes`,'POST',{expectedVersion:d.version,...selected.value.length?{lineIds:selected.value}:{}});await load();await comparisonLoad();});}
async function changeTab(next:'purchase'|'inquiry'|'pricing'|'delivery'){if(busy.value||!checkLeave())return;dirty.value=false;await run(async()=>{if(next==='inquiry')await comparisonLoad();if(next==='pricing'){await comparisonLoad();await loadDraft();}else tab.value=next;});}
async function recover(retry=false){await run(async()=>{const original=operations.pending;if(!original)return;if(retry)await operations.retry();else{const status=await operations.check();if(status==='not_found'){notice.value='暂未找到提交结果；可沿用原操作标识重试。';return;}}const receipt=operations.resultFor(original.key) as {id?:string;orderId?:string}|undefined,id=original.path.match(/^\/sales\/purchase-orders\/([^/]+)/)?.[1]||(original.path==='/sales/purchase-orders'?receipt?.id:receipt?.orderId)||order.value?.id;await bootstrap();draft.value=null;comparison.value=null;generated.value={};undo.value=null;dirty.value=false;if(id){hydrate(await props.api.get<OrderView>('/sales/purchase-orders/'+id));if(order.value!.status==='draft')tab.value='purchase';else if(original.path.startsWith('/quotes/')||['completed','voided','quote_exported','quote_sent'].includes(order.value!.status))tab.value='delivery';else{tab.value='inquiry';await comparisonLoad();}}else{order.value=null;lines.value=[emptyLine()];tab.value='orders';}notice.value='原操作已核实，已重新读取对应订单；不会重复新建。';});}
function beforeLeave(e:BeforeUnloadEvent){if(dirty.value||operations.pending){e.preventDefault();e.returnValue='';}}let startup:Promise<void>=Promise.resolve();onMounted(()=>{window.addEventListener('beforeunload',beforeLeave);startup=run(bootstrap);});
defineExpose({openFromHome:async(id?:string,create=false)=>{await startup;if(id)await open(id);else if(create)await start();}});onBeforeUnmount(()=>{window.removeEventListener('beforeunload',beforeLeave);emit('busyChanged',false);});
async function discardChanges(){await run(async()=>{if(!window.confirm('放弃修改并重新读取？'))return;if(order.value){const wasPricing=tab.value==='pricing';await load();undo.value=null;selected.value=[];method.value=' ';parameter.value='';batchScope.value='all';if(wasPricing){draft.value=null;comparison.value=null;if(writable.value&&order.value.draftId&&order.value.status==='quote_draft'){await comparisonLoad();await loadDraft();}else tab.value='delivery';}else if(tab.value==='inquiry')await comparisonLoad();}else{lines.value=[emptyLine()];dirty.value=false;}});}
</script>
<template>
 <div class="sales-workbench"><div class="heading"><div><p class="eyebrow">销售工作台</p><h1>{{order&&tab!=='orders'?order.hospitalName:'近期采购单'}}</h1><p class="muted" v-if="order&&tab!=='orders'">{{order.orderNo}} · R{{order.revisionNo}} · {{labels[order.status]}} <span v-if="!writable">· 只读</span></p></div><div class="button-row"><button :disabled="busy" @click="home">近期订单</button><button v-if="order&&tab!=='orders'" :disabled="busy||dirty" @click="emit('manageFinance',{orderId:order.id})">查看单笔账期</button><button v-if="order&&tab!=='orders'&&writable&&order.status!=='draft'" :disabled="busy||dirty||!!lifecycleAction" @click="lifecycle('revisions')">创建下一采购修订</button><button v-if="order&&tab!=='orders'&&writable" :disabled="busy||dirty||!!lifecycleAction" @click="lifecycle('void')">整单作废</button><button class="primary" :disabled="busy" @click="start">新建采购单</button></div></div>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><section v-if="operations.pending" class="error"><strong>{{operations.pending.label}}结果尚未核实</strong><p>保留原输入与操作标识，先核对，暂未找到时沿用原操作重试。</p><button :disabled="working" @click="recover()">核对原操作</button><button :disabled="working" @click="recover(true)">沿用原操作重试</button></section>
 <section v-if="lifecycleAction" class="detail-panel"><h2>{{lifecycleAction==='revisions'?'创建下一采购修订':'整张采购单作废'}}</h2><p>{{lifecycleAction==='revisions'?'现版采购明细、报价和文件保留；旧厂家入口关闭，旧医院报价不再接受确认。新修订必须重新校对、冻结和询价。':'终止整张采购需求，关闭填写入口并从需求统计排除，历史和文件继续保留。已有最终确认或应收时禁止此操作。'}}</p><label>原因（必填）<textarea v-model="lifecycleReason" maxlength="500" :disabled="busy"></textarea></label><button class="primary" :disabled="busy||!lifecycleReason.trim()" @click="commitLifecycle">确认{{lifecycleAction==='revisions'?'创建修订':'整单作废'}}</button><button :disabled="busy" @click="lifecycleAction=null">取消</button></section>
 <p v-if="dirty" class="filter-note">有未保存修改。<button :disabled="busy" @click="discardChanges">放弃并重新读取</button></p>
 <nav v-if="order&&tab!=='orders'" class="detail-tabs"><button :class="{selected:tab==='purchase'}" :disabled="busy" @click="changeTab('purchase')">采购明细</button><button :class="{selected:tab==='inquiry'}" :disabled="busy||order.status==='draft'" @click="changeTab('inquiry')">厂家询价与比价</button><button :class="{selected:tab==='pricing'}" :disabled="busy||!order.draftId||!writable" @click="changeTab('pricing')">计价草稿</button><button :class="{selected:tab==='delivery'}" :disabled="busy" @click="changeTab('delivery')">预览与交付</button></nav>
 <template v-if="tab==='orders'"><p class="muted">此页展示最近 100 张可查看采购单；全部记录请使用历史订单的分页查询，详情可继续处理当前负责的未完成单。</p><div class="table-scroll"><table><thead><tr><th>医院 / 单号</th><th>接收日期</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>{{o.hospitalName}}<small>{{o.orderNo}}</small></td><td>{{o.receivedDate}}</td><td>{{labels[o.status]}}</td><td><button :disabled="busy" @click="open(o.id)">{{o.writable&&!['completed','voided'].includes(o.status)?'处理订单':'查阅记录'}}</button></td></tr><tr v-if="!orders.length"><td colspan="4" class="empty">暂无订单。历史检索可使用历史订单页。</td></tr></tbody></table></div></template>
 <template v-if="tab==='purchase'"><div class="form-grid"><label>医院<select v-model="hospitalId" :disabled="busy||!!order"><option v-for="h in hospitals" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>采购员<select v-model="purchaserId" :disabled="busy||!!order"><option v-for="p in hospital?.purchasers||[]" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>实际接收日期<input type="date" v-model="receivedDate" :max="today()" @change="changed" :disabled="busy||!!order&&!order.receivedDateEditable" /></label></div>
 <button :disabled="busy||!writable||!!order&&order.status!=='draft'" @click="catalogOpen=!catalogOpen">{{catalogOpen?'收起商品库':'从商品库选择规格'}}</button><CatalogPanel v-if="catalogOpen" :api="api" :user-id="userId" selectable :locked="working||sourceBusy||childBusy||!!operations.pending" @busy-changed="catalogBusy=$event" @choose="chooseCatalog" @failure="error=$event instanceof Error?$event.message:'商品读取失败'"/><div class="purchase-review"><aside class="original-pane"><h2>原始资料</h2><p class="muted">{{order?'在原单资料中上传或查看采购附件，按原单逐行核对。':'先暂存采购草稿，即可上传并对照原单。'}}</p><SourceFiles v-if="order" :key="order.id+order.revisionId" :api="api" :user-id="userId" :reference="{kind:'purchase_revision',orderId:order.id,revisionId:order.revisionId}" :order-version="order.version" :readonly="!writable||order.status!=='draft'" :locked="working||childBusy||catalogBusy||dirty||!!operations.pending" @busy-changed="sourceBusy=$event" @failure="error=$event instanceof Error?$event.message:'原单读取失败'" @changed="run(load)"/><button v-else :disabled="busy" @click="createSourceDraft">先建立原单资料草稿</button></aside><div><div class="table-scroll"><table><thead><tr><th>品名</th><th>规格</th><th>数量 kg</th><th>采购备注</th><th>已核对</th><th></th></tr></thead><tbody><tr v-for="(l,i) in lines" :key="i"><td><input v-model="l.name" @input="l.checked=false;changed()" :disabled="busy||!writable||!!order&&order.status!=='draft'" maxlength="100" aria-label="药品品名" /></td><td><input v-model="l.spec" @input="l.checked=false;changed()" :disabled="busy||!writable||!!order&&order.status!=='draft'" maxlength="200" aria-label="药品规格" /></td><td><input v-model="l.quantity" @input="l.checked=false;changed()" :disabled="busy||!writable||!!order&&order.status!=='draft'" inputmode="decimal" aria-label="采购数量kg" /></td><td><input v-model="l.remark" @input="l.checked=false;changed()" :disabled="busy||!writable||!!order&&order.status!=='draft'" maxlength="500" aria-label="采购备注" /></td><td><input type="checkbox" v-model="l.checked" @change="changed" :disabled="busy||!writable||!!order&&order.status!=='draft'" aria-label="本行已核对" /></td><td><button :disabled="busy||!writable||lines.length===1||!!order&&order.status!=='draft'" @click="lines.splice(i,1);changed()">移除</button></td></tr></tbody></table></div><div v-if="!order||order.status==='draft'" class="button-row"><button :disabled="busy||!writable||lines.length>=200" @click="lines.push(emptyLine());changed()">添加药品</button><button :disabled="busy||!writable" @click="run(savePurchase)">暂存草稿</button><button class="primary" :disabled="busy||!writable" @click="freeze">复核并冻结</button></div></div></div></template>
 <template v-if="tab==='inquiry'&&order"><div class="factory-pair"><section v-for="slot in ([1,2] as const)" :key="slot" class="detail-panel"><h2>厂家 {{slot===1?'A':'B'}}</h2><template v-if="task(slot)"><p>{{task(slot)!.manufacturerName}} · {{task(slot)!.status}}<small>价格有效至 {{task(slot)!.validUntil||'尚未提交'}}</small></p><div class="button-row"><button v-if="!task(slot)!.linkId" :disabled="busy||!writable" @click="link(task(slot)!)">生成填写链接</button><button :disabled="busy||!writable" @click="taskAction={task:task(slot)!,action:task(slot)!.submissionId?'requote':'regenerate-link'};reason=''">{{task(slot)!.submissionId?'重新询价':'重新生成链接'}}</button><button :disabled="busy||!writable" @click="taskAction={task:task(slot)!,action:'cancel'};reason=''">取消任务</button></div><label v-if="generated[task(slot)!.id]?.url">本次链接（关闭后不能恢复）<input :value="generated[task(slot)!.id].url" readonly @click="($event.target as HTMLInputElement).select()" /></label></template><template v-else><label>选择厂家<select v-model="factory[slot-1]" :disabled="busy||!writable"><option v-for="m in manufacturers" :key="m.id" :value="m.id">{{m.name}}</option></select></label><button :disabled="busy||!writable" @click="assign(slot)">建立询价任务</button></template></section></div>
 <section v-if="taskAction" class="error"><h2>{{taskAction.action==='cancel'?'取消任务':'生成新入口，旧链接及旧页面失效'}}</h2><p v-if="taskAction.action==='requote'">将退出原厂家当前报价，引用该基准的医院报价可能失效。</p><label>操作原因<textarea v-model="reason" maxlength="500"></textarea></label><button :disabled="busy||!reason.trim()" @click="executeTaskAction">确认执行</button><button :disabled="busy" @click="taskAction=null">返回</button></section>
 <div class="button-row"><button :disabled="busy" @click="run(async()=>{await load();await comparisonLoad();})">刷新厂家报价</button><button class="primary" :disabled="busy||!writable||!order.quoteId&&!comparison?.submittedCount" @click="enter">{{order.quoteId&&!order.draftId?'查看报价版本':comparison?.submittedCount===1?'提前进入计价':'进入计价'}}</button></div><div class="table-scroll"><table><thead><tr><th>药品 / 规格</th><th>数量 kg</th><th>厂家 A（元/kg）</th><th>厂家 B（元/kg）</th><th>最低价 / 结果</th></tr></thead><tbody><tr v-for="l in comparison?.lines||[]" :key="l.purchaseLineId"><td>{{l.name}}<small>{{l.spec}}</small></td><td>{{l.quantity}}</td><td v-for="c in l.cells" :key="c.taskId||c.manufacturerName">{{c.price||({unavailable:'缺货',pending:'待提交',expired:'已过期',requote:'重询中'} as any)[c.state]||c.state}}<small>{{c.manufacturerName}}</small></td><td>{{l.lowestPrice||({missing:'双厂家缺货',blocked:'等待完整结果'} as any)[l.kind]}}</td></tr></tbody></table></div></template>
 <template v-if="tab==='pricing'&&draft"><div class="form-grid"><label>批量范围<select v-model="batchScope" :disabled="busy"><option value="all">全部可计价行</option><option value="selected">选中行</option></select></label><label>加价方式<select v-model="method" :disabled="busy"><option value=" ">请选择</option><option v-for="m in methods" :value="m[0]" :key="m[0]">{{m[1]}}</option></select></label><label>参数<input v-model="parameter" :disabled="busy" inputmode="decimal" /></label></div><div class="button-row"><button :disabled="busy||!writable" @click="batch">计算推荐价</button><button :disabled="busy||!undo" @click="undoBatch">撤销最近批量加价</button><button :disabled="busy||dirty" @click="adopt">主动采用最新厂家报价</button></div><p v-if="draft.lines.some(l=>l.hasNewSupplierData)" class="filter-note">有后到或变更报价。当前最终价保留，请主动刷新采用后核对。</p>
 <div class="table-scroll"><table class="pricing-table"><thead><tr><th>选择 / 药品</th><th>数量 kg</th><th>基准厂家</th><th>基准价</th><th>推荐价</th><th>最终价 元/kg</th><th>确认</th><th>亏损原因 / 公开备注</th></tr></thead><tbody><tr v-for="l in draft.lines" :key="l.purchaseLineId"><td><input type="checkbox" :value="l.purchaseLineId" v-model="selected" :disabled="busy" />{{l.name}}<small>{{l.spec}}</small><button :disabled="busy" @click="referenceLineId=l.purchaseLineId">同院历史参考</button></td><td>{{l.quantity}}</td><template v-if="l.kind==='priced'"><td><select :value="l.baseSupplierQuoteLineId" @change="base(l,$event)" :disabled="busy||!writable"><option v-for="c in comparison?.lines.find(x=>x.purchaseLineId===l.purchaseLineId)?.cells.filter(c=>c.state==='quoted')||[]" :key="c.supplierQuoteLineId!" :value="c.supplierQuoteLineId!">{{c.manufacturerName}} · {{c.price}}</option></select><small v-if="!l.baseValid">基准已失效</small></td><td>{{l.basePrice}}</td><td>{{l.recommendedPrice||'未计算'}}<button :disabled="busy||!l.recommendedPrice" @click="adoptRecommended(l)">采用</button></td><td><input v-model="l.finalPrice" @input="finalChanged(l)" :disabled="busy||!writable" inputmode="decimal" /></td><td><input type="checkbox" v-model="l.finalConfirmed" @change="changed" :disabled="busy||!writable||!l.finalPrice" /></td><td><input v-model="l.lossReason" @input="changed" :disabled="busy||!writable" placeholder="低于基准价时必填" maxlength="500" /><input v-model="l.publicRemark" @input="changed" :disabled="busy||!writable" placeholder="对外备注" maxlength="500" /></td></template><td v-else colspan="6">{{l.kind==='missing'?'双厂家明确缺货，保留原采购行':'结果未齐，暂不能导出'}}</td></tr></tbody></table></div><PriceHistory v-if="referenceLine&&order" :key="order.id+draft.id+referenceLine.purchaseLineId" :api="api" :hospital-id="order.hospitalId" :order-id="order.id" :name="referenceLine.name" :spec="referenceLine.spec" :item-id="referencePurchaseLine?.itemId" :item-variant-id="referencePurchaseLine?.itemVariantId" :final-price="referenceLine.finalPrice" :locked="working||childBusy||sourceBusy||catalogBusy||!!operations.pending" @busy-changed="historyBusy=$event" @failure="error=$event instanceof Error?$event.message:'历史参考读取失败'"/><label>医院报价有效至（最多 {{draft.maxValidUntil||'全缺货不适用'}}）<input type="date" v-model="draft.hospitalValidUntil" :max="draft.maxValidUntil||undefined" :disabled="busy||!draft.maxValidUntil" @change="changed" /></label><button class="primary" :disabled="busy||!writable" @click="saveDraft">保存并预览报价</button></template>
 <QuoteDelivery v-if="tab==='delivery'&&order" :key="order.id" :api="api" :order="order" :operations="operations" :locked="working||!!operations.pending" @busy-changed="childBusy=$event" @failure="error=$event instanceof Error?$event.message:'操作失败'" @changed="run(load)" @edit="run(async()=>{await comparisonLoad();await loadDraft();})" />
 </div>
</template>
